        setError(true);
      }
    };

    fetchComparison();
  }, [taskId]);

  if (error) return <div>Failed to load time comparison.</div>;
  if (!comparison) return <div>Loading...</div>;

  return (
    <div>
      <p>Estimated: {comparison.estimated} hours</p>
      <p>Actual: {comparison.actual} hours</p>
    </div>
  );
};

export default TaskDetail;

